import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/MFG.html","title":"MFG","lang":"en-US","frontmatter":{},"git":{"createdTime":1752127539000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":7}]},"readingTime":{"minutes":1.49,"words":446},"filePathRelative":"MFG.md"}`),a={name:`MFG.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="mfg" tabindex="-1"><a class="header-anchor" href="#mfg"><span>MFG</span></a></h1><p><a href="./技術的なメモ.html">技術的なメモ</a>、<a href="./CG.html">CG</a></p><p>私（karino2）が仕事で作っているGPU用フィルタ記述言語。</p><ul><li>公式ページ <a href="https://modernfilterlanguageforgpu.org/" target="_blank" rel="noopener noreferrer">MFG - Modern Filter-language for GPU / MFG Studio</a></li><li><a href="https://karino2.github.io/MFG/ja/" target="_blank" rel="noopener noreferrer">MFGのドキュメント</a></li><li><a href="https://modernfilterlanguageforgpu.org/ja/contest/" target="_blank" rel="noopener noreferrer">MFG - Modern Filter-language for GPU / 学生GPUプログラミングコンテスト</a></li><li><a href="https://www.youtube.com/playlist?list=PL3J_mLcl4YCf1AHEjZO4PjdaIexukpb6e" target="_blank" rel="noopener noreferrer">MFGプログラムシリーズ - YouTube</a></li><li><a href="./ハーフトーン.html">ハーフトーン</a></li><li><a href="./Stippling.html">Stippling</a></li><li><a href="https://pgn.co.jp/blog/mfg_and_ai/#page-content" target="_blank" rel="noopener noreferrer">フィルタ言語「MFG」とAI - 株式会社ピージーエヌ</a></li></ul><h2 id="自分の関連ブログ" tabindex="-1"><a class="header-anchor" href="#自分の関連ブログ"><span>自分の関連ブログ</span></a></h2><ul><li><a href="https://karino2.github.io/2026/02/10/thank_you_for_mfg_challenge.html" target="_blank" rel="noopener noreferrer">MFGチャレンジ、無事終了！</a></li><li><a href="https://karino2.github.io/2025/12/10/mfg_drop_shadow_part1.html" target="_blank" rel="noopener noreferrer">MFG：ドロップシャドウフィルターを作る（その1） </a></li></ul><p>もっと色々あるが全部貼るのは大変なのでたまに気が向いたものだけここに貼る。</p><h2 id="半透明同士のアルファブレンド" tabindex="-1"><a class="header-anchor" href="#半透明同士のアルファブレンド"><span>半透明同士のアルファブレンド</span></a></h2><p>元が半透明な時に半透明を上書きするとどうなるか？というのが良く分からなかったのでメモ。 destの色にcurの色を足した場合どういう結果になるべきか。</p><p>以下の条件を満たすべき。</p><ul><li>destAが1.0の時destRGB*(1-curA)+curRGB*curA</li><li>destAが0.0の時にcurRGB</li><li>curAが0.0の時にdestRGB</li><li>curAが1.0の時にcurRGB</li><li>destAが小さい時はcurRGBに近づく</li><li>curAが小さい時はdestRGBに近づく</li></ul><p>これらを全て満たす数式は以下か？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">{destA*destRGB*(1-curA)+curRGB*curA}/{(1-destA)*curA+destA} </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>分母はdestAと1.0をcurAでアルファブレンドした結果、、、かな？ これはアルファの結果にもなっているか。</p><p>つまりMFGのコードにすると以下か。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">fn</span> <span class="token function">blend</span> <span class="token operator">|</span> dest<span class="token punctuation">:</span> <span class="token builtin">f32v4</span><span class="token punctuation">,</span> cur<span class="token punctuation">:</span> <span class="token builtin">f32v4</span> <span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> resA <span class="token operator">=</span> mix<span class="token punctuation">(</span>dest<span class="token punctuation">.</span>w<span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">,</span> cur<span class="token punctuation">.</span>w<span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">let</span> resBGR <span class="token operator">=</span> mix<span class="token punctuation">(</span>dest<span class="token punctuation">.</span>w<span class="token operator">*</span>dest<span class="token punctuation">.</span>xyz<span class="token punctuation">,</span> cur<span class="token punctuation">.</span>xyz<span class="token punctuation">,</span> cur<span class="token punctuation">.</span>w<span class="token punctuation">)</span><span class="token operator">/</span>resA</span>
<span class="line">  <span class="token builtin">ifel</span><span class="token punctuation">(</span>cur<span class="token punctuation">.</span>w <span class="token operator">&lt;</span> <span class="token number">0.0001</span><span class="token punctuation">,</span></span>
<span class="line">        dest<span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">[</span><span class="token operator">*</span>resBGR<span class="token punctuation">,</span> resA<span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="グレースケール" tabindex="-1"><a class="header-anchor" href="#グレースケール"><span>グレースケール</span></a></h2><p>良く使うのでコードを書いておく。</p><p><a href="./【書籍】PrinciplesOfDigitalImageProcessing.html">【書籍】PrinciplesOfDigitalImageProcessing</a>の一冊目のp202とp203に以下のweightが載っている。</p><ul><li><code>(0.299, 0.587, 0.114)</code> テレビの信号処理で提案されて業界で良く使われているもの</li><li><code>(0.215, 0.7154, 0.072)</code> ITU-BT.709の推奨、この本の他の場所ではこれを使っている</li></ul><p>どちらもlineariseしたあとに使う。</p><p>また、lineariseする前に使う近似weightがVol 2.のp111, 6.17に書いてあって、それは</p><ul><li><code>(0.309, 0.609, 0.082)</code></li></ul><p>となっている。</p><p>また、<a href="./【書籍】OpenGL4ShadingLanguageCook.html">【書籍】OpenGL4ShadingLanguageCook</a>のサンプルコードでは、例えばEdge Detectionのフィルタのluminanceは以下のベクトルをかけて求めている。</p><ul><li><code>(0.2126, 0.7152, 0.0722)</code></li></ul><p>これはITU-BT.709の推奨と似た数値なのでlineariseしないと駄目な気がするが、ホスト側でしているのかな？</p><h3 id="mfgのとりあえずのコード" tabindex="-1"><a class="header-anchor" href="#mfgのとりあえずのコード"><span>MFGのとりあえずのコード</span></a></h3><p>とりあえずは以下のようにするのが一番良いか。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line">  <span class="token keyword">let</span> gray <span class="token operator">=</span> to_xyza<span class="token punctuation">(</span><span class="token builtin">input_u8</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> y<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span>y</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>動作確認としては以下。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">def</span> <span class="token tensor-name class-name">result_u8</span> <span class="token operator">|</span>x<span class="token punctuation">,</span> y<span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> gray <span class="token operator">=</span> to_xyza<span class="token punctuation">(</span><span class="token builtin">input_u8</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> y<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span>y</span>
<span class="line">  <span class="token punctuation">[</span>gray<span class="token punctuation">,</span> gray<span class="token punctuation">,</span> gray<span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">]</span> <span class="token operator">|&gt;</span> to_u8color<span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上記の式で計算するのもそんなに大変ではないが、とりあえずこれを評価して駄目だった事はない。</p><h2 id="ハッシュ" tabindex="-1"><a class="header-anchor" href="#ハッシュ"><span>ハッシュ</span></a></h2><p>この論文が素晴らしく良くまとまっている。</p><p><a href="https://jcgt.org/published/0009/03/02/" target="_blank" rel="noopener noreferrer">Hash Functions for GPU Rendering (JCGT)</a></p><p>2次元で使うならPCGかな。<code>hash(x + hash(y))</code> とするのがperlinノイズで使っていた手法とか。 MFGはハットが累乗に使われているのでxorが関数なのに注意。</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">fn</span> <span class="token function">hash</span> <span class="token operator">|</span>i<span class="token punctuation">:</span> <span class="token builtin">i32</span><span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> state <span class="token operator">=</span> <span class="token builtin">u32</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span> <span class="token operator">*</span> 747796405u <span class="token operator">+</span> 2891336453u</span>
<span class="line">  <span class="token keyword">let</span> word <span class="token operator">=</span> <span class="token builtin">xor</span><span class="token punctuation">(</span><span class="token punctuation">(</span>state <span class="token operator">&gt;&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">(</span>state <span class="token operator">&gt;&gt;</span> 28u<span class="token punctuation">)</span> <span class="token operator">+</span> 4u<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span> state<span class="token punctuation">)</span> <span class="token operator">*</span> 277803737u</span>
<span class="line">  <span class="token builtin">i32</span><span class="token punctuation">(</span><span class="token builtin">xor</span><span class="token punctuation">(</span><span class="token punctuation">(</span>word <span class="token operator">&gt;&gt;</span> 22u<span class="token punctuation">)</span><span class="token punctuation">,</span> word<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function">hash_xy</span> <span class="token operator">|</span>x<span class="token punctuation">:</span><span class="token builtin">i32</span><span class="token punctuation">,</span> y<span class="token punctuation">:</span><span class="token builtin">i32</span><span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">  hash<span class="token punctuation">(</span>x <span class="token operator">+</span> hash<span class="token punctuation">(</span>y<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ちなみにuint32を0.0〜1.0にマップするには以下が良いとか。（関数の外はi32で統一、という方針に従い、i32で渡してu32にキャストして計算している）</p><div class="language-mfg line-numbers-mode" data-highlighter="prismjs" data-ext="mfg"><pre><code class="language-mfg"><span class="line"><span class="token keyword">fn</span> <span class="token function">map_to_f32</span> <span class="token operator">|</span>uval<span class="token punctuation">:</span> <span class="token builtin">i32</span><span class="token operator">|</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> inv <span class="token operator">=</span> <span class="token number">1.0</span> <span class="token operator">/</span> <span class="token number">4294967295.0</span></span>
<span class="line">  <span class="token builtin">f32</span><span class="token punctuation">(</span><span class="token builtin">u32</span><span class="token punctuation">(</span>uval<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token operator">*</span>inv</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> tmp2 <span class="token operator">=</span> map_to_f32<span class="token punctuation">(</span><span class="token number">0xf0ffffff</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token attribute atrule">@print_expr</span><span class="token punctuation">(</span>tmp2<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};